/**
 * DSH 对话页的图片附件 —— 「上传后的附件」与「能过桥的那点东西」之间的唯一转换层。
 *
 * 为什么要它：DSH 桥接是纯文本通道（BridgeFrame 只有文本与工具帧，PromptRequest 只有
 * text 字段），图片没有原生位置可放。于是约定两样东西：
 *  1) 一行给人看、也给 AI 看的标记 `[图片 #<file_id>: <name>]`——气泡据此渲染缩略图，
 *     会话里的 AI 据此知道"这条消息带了图"，刷新后也还在（不靠本地内存）；
 *  2) 一段机器块 `<copree-attachments>…</copree-attachments>`——新插件（>=0.2.0）
 *     会把它解出来落成文件、换成可读路径，老插件则整段留在文本里（所以只在插件支持时才发）。
 *
 * 压缩在这里做：桥接传的是 base64 文本，原图动辄几 MB，先按长边收敛再编码。
 */
import { getApiBaseUrl } from '../api/client'

/** DSH 侧多模态看得清、又不至于把正文撑爆的长边上限（与主流 VLM 的常用上限同量级） */
const MAX_EDGE = 1568
const JPEG_QUALITY = 0.85
/** 重压一档：首次编码后仍然过大时用（长边与质量一起退一步） */
const RETRY_EDGE = 1024
const RETRY_QUALITY = 0.7
/** 单张图片编码后的文本上限：再大就不该往对话里塞了，宁可让用户自己压 */
const MAX_ENCODED_CHARS = 4_000_000

export interface DshImagePayload {
  name: string
  mime: string
  /** 纯 base64（不带 data: 前缀）：插件按这段直接落盘 */
  data: string
}

export interface DshImageRef {
  file_id: number
  name: string
}

/** 人可读、AI 可读、刷新后仍在的图片标记 */
export function imageMarker(fileId: number, name: string): string {
  return `[图片 #${fileId}: ${name}]`
}

/** 从消息正文里取回图片标记（气泡渲染缩略图用；没有标记就是没有图） */
export function imageRefsIn(text: string): DshImageRef[] {
  const out: DshImageRef[] = []
  const re = /\[图片 #(\d+)(?:: ([^\]]*))?\]/g
  let m: RegExpExecArray | null
  while ((m = re.exec(text || '')) !== null) {
    out.push({ file_id: Number(m[1]), name: m[2] || '' })
  }
  return out
}

/**
 * 展示用：把图片标记从正文里摘掉（缩略图已经表达了它）。
 * 只摘我们自己写的那种标记，插件补的路径行照旧显示——那是"图存哪了"的凭据。
 */
export function stripImageMarkers(text: string): string {
  return (text || '')
    .split('\n')
    .filter((line) => !/^\[图片 #\d+(?:: [^\]]*)?\]$/.test(line.trim()))
    .join('\n')
    .trim()
}

/**
 * 插件是否吃附件块。用版本号做能力开关：老插件会把整段 base64 当正文留在会话里，
 * 那比"不带图"更糟，所以宁可退化成只发标记。
 */
export function supportsImageAttachments(version?: string): boolean {
  if (!version) return false
  const [major, minor] = version.split('.').map((n) => Number(n))
  if (!Number.isFinite(major) || !Number.isFinite(minor)) return false
  return major > 0 || minor >= 2
}

/** 附件块（一张或多张）：插件认得这个围栏，别的模型/工具只当是普通文本 */
export function packAttachmentBlock(payloads: DshImagePayload[]): string {
  if (payloads.length === 0) return ''
  return `\n\n<copree-attachments>${JSON.stringify(payloads)}</copree-attachments>`
}

/** 附件缩略图地址：与群视界对话同一条下载路径（token 走 query，img 标签带不上 header） */
export function attachmentUrl(fileId: number): string {
  return `${getApiBaseUrl()}/fs/download/${fileId}?token=${localStorage.getItem('access_token') || ''}`
}

/** 画布重编码：长边收敛 + 按原类型选编码（png 保留透明，其余走 jpeg） */
async function downscale(blob: Blob, mime: string, edge: number, quality: number): Promise<{ data: string; mime: string }> {
  const bitmap = await createImageBitmap(blob)
  const scale = Math.min(1, edge / Math.max(bitmap.width, bitmap.height))
  const w = Math.max(1, Math.round(bitmap.width * scale))
  const h = Math.max(1, Math.round(bitmap.height * scale))
  const canvas = document.createElement('canvas')
  canvas.width = w
  canvas.height = h
  const ctx = canvas.getContext('2d')
  if (!ctx) throw new Error('canvas unavailable')
  ctx.drawImage(bitmap, 0, 0, w, h)
  bitmap.close?.()
  const outMime = mime === 'image/png' ? 'image/png' : 'image/jpeg'
  const url = canvas.toDataURL(outMime, quality)
  return { data: url.slice(url.indexOf(',') + 1), mime: outMime }
}

/**
 * 取回上传后的图片并编码成可过桥的 base64。
 * 为什么要从服务端取回而不是用手里那个 File：附件经过 useAttachmentUpload 后 File 已置空，
 * 拖拽/粘贴进来的文件更是没有第二份；服务端那份才是"AI 将来会看到的那张"。
 */
export async function loadImagePayload(fileId: number, name: string, mime: string): Promise<DshImagePayload> {
  const res = await fetch(attachmentUrl(fileId).split('?')[0], {
    headers: { Authorization: 'Bearer ' + (localStorage.getItem('access_token') || '') },
  })
  if (!res.ok) throw new Error(`附件读取失败（HTTP ${res.status}）`)
  const blob = await res.blob()
  const sourceMime = mime || blob.type || 'image/png'
  let encoded = await downscale(blob, sourceMime, MAX_EDGE, JPEG_QUALITY)
  if (encoded.data.length > MAX_ENCODED_CHARS) {
    encoded = await downscale(blob, sourceMime, RETRY_EDGE, RETRY_QUALITY)
  }
  if (encoded.data.length > MAX_ENCODED_CHARS) throw new Error('图片过大，压缩后仍超出上限')
  return { name, mime: encoded.mime, data: encoded.data }
}
